<script setup lang="ts">import type { PublicFormSlot } from '~/types/public-form';defineProps<{dates:string[];selectedDate:string|null;slots:PublicFormSlot[];selectedSlot:PublicFormSlot|null;formatDate:(v:string)=>string}>();defineEmits(['select-date','select-slot'])</script>
<template><div class="space-y-4"><div><p class="mb-2 font-medium">Data</p><div class="flex flex-wrap gap-2"><SelectableBadge v-for="d in dates" :key="d" :selected="selectedDate===d" @click="$emit('select-date',d)">{{ formatDate(d) }}</SelectableBadge></div></div><div><p class="mb-2 font-medium">Horário</p><div class="grid gap-2 md:grid-cols-2"><TimeSlotCard v-for="s in slots" :key="s.id" :selected="selectedSlot?.id===s.id" :time="`${s.startTime} — ${s.endTime}`" :capacity="s.capacity" @click="$emit('select-slot',s)"/></div></div></div></template>
